import{_ as i,c as e,o as a,a0 as l}from"./chunks/framework.DKRgXLPU.js";const o=JSON.parse('{"title":"Leadership in Pétanque","description":"Develop leadership skills that elevate your team\'s performance. Learn how to lead effectively whether you\'re the captain or a supporting player.","frontmatter":{"title":"Leadership in Pétanque","description":"Develop leadership skills that elevate your team\'s performance. Learn how to lead effectively whether you\'re the captain or a supporting player."},"headers":[],"relativePath":"it/blog/team-leadership.md","filePath":"it/blog/team-leadership.md"}');const r=i({name:"it/blog/team-leadership.md"},[["render",function(i,o,r,t,s,n){return a(),e("div",null,[...o[0]||(o[0]=[l('<h1 id="leadership-nel-gioco-delle-bocce" tabindex="-1">Leadership nel gioco delle bocce <a class="header-anchor" href="#leadership-nel-gioco-delle-bocce" aria-label="Permalink to &quot;Leadership nel gioco delle bocce&quot;">​</a></h1><p>La leadership nel gioco delle bocce non consiste solo nell&#39;essere il capitano o il miglior giocatore. Riguarda l&#39;influenza, il supporto e il far emergere il meglio dalla propria squadra. Ogni giocatore può guidare in modi diversi.</p><h2 id="cos-39-e-la-leadership-nel-gioco-delle-bocce" tabindex="-1">Cos&#39;è la leadership nel gioco delle bocce? <a class="header-anchor" href="#cos-39-e-la-leadership-nel-gioco-delle-bocce" aria-label="Permalink to &quot;Cos&amp;#39;è la leadership nel gioco delle bocce?&quot;">​</a></h2><p>Una leadership efficace nel gioco delle bocce significa:</p><ul><li>Prendere buone decisioni sotto pressione</li><li>Supportare i compagni di squadra nelle sfide</li><li>Mantenere la concentrazione e l&#39;energia del team</li><li>Modellare il comportamento che vuoi vedere</li><li>Assumersi la responsabilità dei risultati del team</li></ul><h2 id="tipi-di-leadership" tabindex="-1">Tipi di leadership <a class="header-anchor" href="#tipi-di-leadership" aria-label="Permalink to &quot;Tipi di leadership&quot;">​</a></h2><h3 id="leadership-posizionale" tabindex="-1">Leadership posizionale <a class="header-anchor" href="#leadership-posizionale" aria-label="Permalink to &quot;Leadership posizionale&quot;">​</a></h3><p>Il capitano o il caposquadra designato:</p><ul><li>Prende decisioni strategiche finali</li><li>Rappresenta ufficialmente la squadra</li><li>Gestisce le dinamiche di squadra</li><li>Stabilisce il tono e la cultura</li></ul><h3 id="leadership-delle-prestazioni" tabindex="-1">Leadership delle prestazioni <a class="header-anchor" href="#leadership-delle-prestazioni" aria-label="Permalink to &quot;Leadership delle prestazioni&quot;">​</a></h3><p>Leadership attraverso l&#39;eccellenza:</p><ul><li>Dimostrare abilità e coerenza</li><li>Mostrare come gestire la pressione</li><li>Stabilire gli standard attraverso l&#39;azione</li><li>Ispirare attraverso la performance</li></ul><h3 id="leadership-emotiva" tabindex="-1">Leadership emotiva <a class="header-anchor" href="#leadership-emotiva" aria-label="Permalink to &quot;Leadership emotiva&quot;">​</a></h3><p>Gestire l&#39;energia e il morale del team:</p><ul><li>Mantenere un atteggiamento positivo sotto pressione</li><li>Supportare i compagni di squadra in difficoltà</li><li>Celebrare i successi</li><li>Mantenere la prospettiva</li></ul><h3 id="leadership-tattica" tabindex="-1">Leadership tattica <a class="header-anchor" href="#leadership-tattica" aria-label="Permalink to &quot;Leadership tattica&quot;">​</a></h3><p>Contribuire al pensiero strategico:</p><ul><li>Leggere bene il gioco</li><li>Offrire spunti preziosi</li><li>Vedere schemi che altri non vedono</li><li>Pensare al futuro</li></ul><h2 id="il-leader-efficace" tabindex="-1">Il leader efficace <a class="header-anchor" href="#il-leader-efficace" aria-label="Permalink to &quot;Il leader efficace&quot;">​</a></h2><h3 id="in-pratica" tabindex="-1">In pratica <a class="header-anchor" href="#in-pratica" aria-label="Permalink to &quot;In pratica&quot;">​</a></h3><ul><li>Arriva preparato e concentrato</li><li>Lavora duro e incoraggia gli altri</li><li>Fornisce un feedback costruttivo</li><li>Crea un ambiente di formazione positivo</li></ul><h3 id="prima-della-competizione" tabindex="-1">Prima della competizione <a class="header-anchor" href="#prima-della-competizione" aria-label="Permalink to &quot;Prima della competizione&quot;">​</a></h3><ul><li>Assicura che il team sia preparato</li><li>Stabilisce aspettative chiare</li><li>Gestisce i nervi pre-partita</li><li>Crea concentrazione e sicurezza</li></ul><h3 id="durante-la-competizione" tabindex="-1">Durante la competizione <a class="header-anchor" href="#durante-la-competizione" aria-label="Permalink to &quot;Durante la competizione&quot;">​</a></h3><ul><li>Prende decisioni chiare e tempestive</li><li>Supporta visibilmente i compagni di squadra</li><li>Mantiene la calma sotto pressione</li><li>Adatta la strategia secondo necessità</li></ul><h3 id="dopo-la-competizione" tabindex="-1">Dopo la competizione <a class="header-anchor" href="#dopo-la-competizione" aria-label="Permalink to &quot;Dopo la competizione&quot;">​</a></h3><ul><li>Gestisce le vittorie con grazia</li><li>Gestisce le perdite con prospettiva</li><li>Conduce debriefing costruttivi</li><li>Mantiene i rapporti di squadra</li></ul><h2 id="sfide-di-leadership" tabindex="-1">Sfide di leadership <a class="header-anchor" href="#sfide-di-leadership" aria-label="Permalink to &quot;Sfide di leadership&quot;">​</a></h2><h3 id="prendere-decisioni-difficili" tabindex="-1">Prendere decisioni difficili <a class="header-anchor" href="#prendere-decisioni-difficili" aria-label="Permalink to &quot;Prendere decisioni difficili&quot;">​</a></h3><p>A volte è necessario:</p><ul><li>Scegli tra opzioni senza una risposta chiara</li><li>Non essere d&#39;accordo con i compagni di squadra</li><li>Assumersi la responsabilità dei risultati</li><li>Agire con decisione nonostante l&#39;incertezza</li></ul><p><strong>Approccio:</strong></p><ul><li>Raccogli rapidamente i dati</li><li>Prendi la decisione</li><li>Impegnarsi pienamente</li><li>Impara dai risultati</li></ul><h3 id="gestione-dei-conflitti" tabindex="-1">Gestione dei conflitti <a class="header-anchor" href="#gestione-dei-conflitti" aria-label="Permalink to &quot;Gestione dei conflitti&quot;">​</a></h3><p>Gli attriti di squadra sono inevitabili:</p><ul><li>Diverse opinioni sulla strategia</li><li>Frustrazione dopo gli errori</li><li>Scontri di personalità</li><li>Impegno diseguale</li></ul><p><strong>Approccio:</strong></p><ul><li>Affrontare i problemi in anticipo</li><li>Ascolta tutte le prospettive</li><li>Concentrarsi sulle soluzioni</li><li>Mantenere il rispetto</li></ul><h3 id="sostenere-i-giocatori-in-difficolta" tabindex="-1">Sostenere i giocatori in difficoltà <a class="header-anchor" href="#sostenere-i-giocatori-in-difficolta" aria-label="Permalink to &quot;Sostenere i giocatori in difficoltà&quot;">​</a></h3><p>Quando un compagno di squadra non rende al meglio:</p><ul><li>Non aggiungere pressione</li><li>Offrire un supporto specifico e positivo</li><li>Se necessario, adattare la strategia</li><li>Mantieni la fiducia in loro</li></ul><h3 id="gestire-le-proprie-difficolta" tabindex="-1">Gestire le proprie difficoltà <a class="header-anchor" href="#gestire-le-proprie-difficolta" aria-label="Permalink to &quot;Gestire le proprie difficoltà&quot;">​</a></h3><p>Anche i leader hanno difficoltà:</p><ul><li>Riconoscilo (a te stesso)</li><li>Non lasciare che influenzi la tua leadership</li><li>Appoggiarsi ai compagni di squadra</li><li>Resilienza del modello</li></ul><h2 id="stili-di-leadership" tabindex="-1">Stili di leadership <a class="header-anchor" href="#stili-di-leadership" aria-label="Permalink to &quot;Stili di leadership&quot;">​</a></h2><h3 id="il-comandante" tabindex="-1">Il Comandante <a class="header-anchor" href="#il-comandante" aria-label="Permalink to &quot;Il Comandante&quot;">​</a></h3><ul><li>Diretto e deciso</li><li>Aspettative chiare</li><li>Prende il controllo in caso di crisi</li><li>Rischio: può essere opprimente</li></ul><h3 id="l-39-allenatore" tabindex="-1">L&#39;allenatore <a class="header-anchor" href="#l-39-allenatore" aria-label="Permalink to &quot;L&amp;#39;allenatore&quot;">​</a></h3><ul><li>Sviluppa gli altri</li><li>Fa domande</li><li>Sviluppa capacità</li><li>Rischio: può essere lento in caso di crisi</li></ul><h3 id="il-collaboratore" tabindex="-1">Il Collaboratore <a class="header-anchor" href="#il-collaboratore" aria-label="Permalink to &quot;Il Collaboratore&quot;">​</a></h3><ul><li>Cerca input</li><li>Crea consenso</li><li>Valorizza tutte le voci</li><li>Rischio: può essere indeciso</li></ul><h3 id="il-sostenitore" tabindex="-1">Il sostenitore <a class="header-anchor" href="#il-sostenitore" aria-label="Permalink to &quot;Il sostenitore&quot;">​</a></h3><ul><li>Si concentra sulle relazioni</li><li>Crea sicurezza</li><li>Incoraggia e afferma</li><li>Rischio: può evitare dure verità</li></ul><p><strong>I leader migliori adattano il loro stile alla situazione.</strong></p><h2 id="sviluppare-capacita-di-leadership" tabindex="-1">Sviluppare capacità di leadership <a class="header-anchor" href="#sviluppare-capacita-di-leadership" aria-label="Permalink to &quot;Sviluppare capacità di leadership&quot;">​</a></h2><h3 id="consapevolezza-di-se" tabindex="-1">Consapevolezza di sé <a class="header-anchor" href="#consapevolezza-di-se" aria-label="Permalink to &quot;Consapevolezza di sé&quot;">​</a></h3><p>Conosci il tuo:</p><ul><li>Stile di leadership naturale</li><li>Punti di forza e di debolezza</li><li>Impatto sugli altri</li><li>Fattori scatenanti e reazioni</li></ul><h3 id="intelligenza-emotiva" tabindex="-1">Intelligenza emotiva <a class="header-anchor" href="#intelligenza-emotiva" aria-label="Permalink to &quot;Intelligenza emotiva&quot;">​</a></h3><p>Sviluppare la capacità di:</p><ul><li>Riconoscere le emozioni (le tue e quelle degli altri)</li><li>Gestisci le tue risposte</li><li>Empatizzare con i compagni di squadra</li><li>Navigare le dinamiche sociali</li></ul><h3 id="capacita-di-comunicazione" tabindex="-1">Capacità di comunicazione <a class="header-anchor" href="#capacita-di-comunicazione" aria-label="Permalink to &quot;Capacità di comunicazione&quot;">​</a></h3><p>Pratica:</p><ul><li>Messaggi chiari e concisi</li><li>Ascolto attivo</li><li>Fornire feedback costruttivi</li><li>Conversazioni difficili</li></ul><h3 id="il-processo-decisionale" tabindex="-1">Il processo decisionale <a class="header-anchor" href="#il-processo-decisionale" aria-label="Permalink to &quot;Il processo decisionale&quot;">​</a></h3><p>Migliorare attraverso:</p><ul><li>Analisi delle decisioni passate</li><li>Cerco feedback</li><li>Imparare dagli errori</li><li>Allenarsi sotto pressione</li></ul><h2 id="leadership-senza-titolo" tabindex="-1">Leadership senza titolo <a class="header-anchor" href="#leadership-senza-titolo" aria-label="Permalink to &quot;Leadership senza titolo&quot;">​</a></h2><p>Non è necessario essere capitano per guidare:</p><h3 id="dare-il-buon-esempio" tabindex="-1">Dare il buon esempio <a class="header-anchor" href="#dare-il-buon-esempio" aria-label="Permalink to &quot;Dare il buon esempio&quot;">​</a></h3><ul><li>Presentarsi preparati</li><li>Fai tutto il possibile</li><li>Gestire bene le avversità</li><li>Supportare i compagni di squadra</li></ul><h3 id="guida-attraverso-il-supporto" tabindex="-1">Guida attraverso il supporto <a class="header-anchor" href="#guida-attraverso-il-supporto" aria-label="Permalink to &quot;Guida attraverso il supporto&quot;">​</a></h3><ul><li>Incoraggiare gli altri</li><li>Offrire aiuto</li><li>Celebrare il successo dei compagni di squadra</li><li>Sii affidabile</li></ul><h3 id="guida-attraverso-il-contributo" tabindex="-1">Guida attraverso il contributo <a class="header-anchor" href="#guida-attraverso-il-contributo" aria-label="Permalink to &quot;Guida attraverso il contributo&quot;">​</a></h3><ul><li>Condividi le osservazioni</li><li>Offrire idee con rispetto</li><li>Prendi l&#39;iniziativa</li><li>Riempire gli spazi vuoti</li></ul><h2 id="la-mentalita-della-leadership" tabindex="-1">La mentalità della leadership <a class="header-anchor" href="#la-mentalita-della-leadership" aria-label="Permalink to &quot;La mentalità della leadership&quot;">​</a></h2><h3 id="responsabilita-anziche-colpa" tabindex="-1">Responsabilità anziché colpa <a class="header-anchor" href="#responsabilita-anziche-colpa" aria-label="Permalink to &quot;Responsabilità anziché colpa&quot;">​</a></h3><p>I leader si assumono la responsabilità:</p><ul><li>&quot;Non abbiamo agito bene&quot; non &quot;Hanno sbagliato&quot;</li><li>&quot;Avrei dovuto comunicare meglio&quot; non &quot;Non mi hanno ascoltato&quot;</li></ul><h3 id="la-squadra-prima-di-se-stessi" tabindex="-1">La squadra prima di se stessi <a class="header-anchor" href="#la-squadra-prima-di-se-stessi" aria-label="Permalink to &quot;La squadra prima di se stessi&quot;">​</a></h3><p>I leader danno priorità al successo del team:</p><ul><li>Celebrare i risultati del team</li><li>Condividi generosamente il merito</li><li>Prendersi la colpa personalmente</li><li>Metti al primo posto le esigenze della squadra</li></ul><h3 id="crescita-prima-del-comfort" tabindex="-1">Crescita prima del comfort <a class="header-anchor" href="#crescita-prima-del-comfort" aria-label="Permalink to &quot;Crescita prima del comfort&quot;">​</a></h3><p>I leader accettano la sfida:</p><ul><li>Cerca situazioni difficili</li><li>Imparare dagli errori</li><li>Spingere per il miglioramento</li><li>Modello di crescita continua</li></ul><h2 id="quando-la-leadership-fallisce" tabindex="-1">Quando la leadership fallisce <a class="header-anchor" href="#quando-la-leadership-fallisce" aria-label="Permalink to &quot;Quando la leadership fallisce&quot;">​</a></h2><p>Anche i buoni leader a volte falliscono:</p><ul><li>Le decisioni sbagliate capitano</li><li>Le squadre perdono nonostante una buona leadership</li><li>Le relazioni sono tese</li></ul><p><strong>Recupero:</strong></p><ol><li>Riconosci cosa è successo</li><li>Assumersi la responsabilità appropriata</li><li>Impara le lezioni</li><li>Andare avanti con umiltà</li></ol><hr><p>| <em>Correlato: <a href="/it/education/team-player/">Dinamiche di squadra</a> | <a href="/it/istruzione/giocatore-di-squadra/comunicazione">Comunicazione</a> | <a href="/it/blog/team-chemistry">Costruire la chimica di squadra</a></em> |</p>',92)])])}]]);export{o as __pageData,r as default};
